  Lemma imemset_wloop : forall (K : nat) (i : Z) (m1 : amem) (bs : list byte) (Q : Z -> Prop),
    Z.to_nat (n - i) = K ->
    u8arr bsegs m1 A bs -> filled (Z_to_bv 8 0) bs Q -> length bs = Z.to_nat n ->
    mem_inv bsegs m1 -> munch W m m1 -> wmono bsegs m m1 ->
