  (ia = true -> forall j, 0 <= j < AIA_MAP1_LEN / 8 -> bytes_at bsegs m (AIA_MAP1 + 8 * j) (le8 (Z_to_bv 64 0))) ->
  rw_cells bsegs m 0xb2108 [C8 (Z_to_bv 64 0x149da0)] -> rw_cells bsegs m 0x149da0 [C8 (Z_to_bv 64 4096)] ->
